CREATE PROCEDURE [dbo].[bkp_spSearchInspectionScheduler_04Apr2024]
	@LicenceID int, @StaffAccountID int, @Filter varchar(100), @DateFrom DateTime, @DateTo DateTime, @ApplicationTypeID int, @PageNumber int, @RowspPage int
AS
BEGIN
	SET NOCOUNT ON
	declare @query varchar(MAX)
	declare @sql varchar(8000)
		
	set @sql = 'select i.*, a.ApplicationNo, a.NatureOfWorks, a.ApplicationTypeID, p.PropertyTypeID, p.Address, p.Suburb, TRIM(CONCAT(sa.FirstName, '' '', sa.LastName)) as Name, sa.Mobile, sa.Email, sa.FirstName, sa.LastName, at.FSMTypeName, p.PropertyID, p.Longitude, p.Latitude, a.Status as ApplicationStatus from Inspection i join Application a on i.ApplicationID = a.ApplicationID join ApplicationType at on a.ApplicationTypeID = at.ApplicationTypeID left join StaffAccount sa on i.AssignedInspectionOfficer = sa.StaffAccountID left join Property p on (i.ApplicationID = p.ApplicationID and p.PropertyID in (select max(PropertyID) from Property group by ApplicationID)) where a.LicenceID = ' + CAST(@LicenceID as varchar) + ' and a.State = 1'
	
	if (@ApplicationTypeID != 0)
	begin
		set @sql = @sql + ' and a.ApplicationTypeID = ' + CAST(@ApplicationTypeID as varchar);
	end
	
	if (@StaffAccountID != 0)
	begin
		set @sql = @sql + ' and i.AssignedInspectionOfficer = ' + CAST(@StaffAccountID as varchar);
	end
	
	if (@Filter = '')
	begin
		if (@DateFrom is not null)
		begin
			set @sql = @sql + ' and i.ScheduledDate >= ''' + convert(varchar(10), @DateFrom, 120) + '''';
		end
		if (@DateTo is not null)
		begin
			set @sql = @sql + ' and i.ScheduledDate <= ''' + convert(varchar(10), @DateTo, 120) + '''';
		end
	end
	
	if (@Filter = 'Overdue')
	begin
		set @sql = @sql + ' and i.ScheduledDate < ''' + convert(varchar(10), getdate(), 120) + ''' and i.InspectionDecision is null';
		if (@DateFrom is not null)
		begin
			set @sql = @sql + ' and i.ScheduledDate >= ''' + convert(varchar(10), @DateFrom, 120) + '''';
		end
		if (@DateTo is not null)
		begin
			set @sql = @sql + ' and i.ScheduledDate <= ''' + convert(varchar(10), @DateTo, 120) + '''';
		end
	end
	
	if (@Filter = 'Unscheduled')
	begin
		set @sql = @sql + ' and i.ScheduledDate is null and i.InspectionDecision is null';
	end	
	
	set @query ='
				WITH InspectionView AS (
					SELECT ROW_NUMBER() OVER(ORDER BY t.ScheduledDate, t.ScheduledTime, t.Suburb) AS RowNumber, * FROM (' + @sql + ') t 
				)
				SELECT * FROM InspectionView WHERE RowNumber BETWEEN ((' + CAST(@PageNumber as varchar) + ' - 1) * ' + CAST(@RowspPage as varchar) + ' + 1) AND (' + CAST(@PageNumber as varchar) + ' * ' + CAST(@RowspPage as varchar) + ')
				SELECT COUNT(*) as total FROM (' + @sql + ') t 
				'
	
	--print @query
	exec (@query)



END

