-- Description: Get values from application table related tables expression should be following format [%TABLE_NAME#COLUMN_NAME#%].                
-- EXEC dbo.GetApplicationTableRelatedValues N'[%Application#ApplicationNo#%]', 137946, ;           
-- =============================================         
CREATE PROCEDURE [dbo].[GetApplicationTableRelatedValues_OLD]  
(    
  @expression VARCHAR(MAX),    
  @applicationId INT,    
  @documentId INT,  
  @ReturnValue NVARCHAR(100) OUT    
)    
AS     
BEGIN    
    DECLARE @TableName VARCHAR(MAX);    
  DECLARE @ColumnName VARCHAR(MAX);    
  DECLARE @SubStr VARCHAR(MAX);    
  DECLARE @SQL NVARCHAR(MAX) = '';    
    
  SET @SubStr = REPLACE(REPLACE(@expression,'%]', ''),'[%', '');    
     
  SELECT  value INTO #data FROM STRING_SPLIT ( @SubStr , '#' ) WHERE RTRIM(value) <> '';     
  IF (SELECT COUNT(value) FROM #data) > 1    
  BEGIN    
   SELECT TOP(1) @TableName = value     
   FROM #data;    
    
   SELECT @ColumnName = value    
   FROM #data    
   WHERE value <> @TableName;    
    
   SET @ColumnName = CONCAT('@OutValue = ', @ColumnName);    
    
   SELECT @SQL = CASE WHEN @TableName = 'Application'    
     THEN 'SELECT ' + @ColumnName + ' FROM Application WHERE ApplicationID = ' + CONVERT(VARCHAR(100), @applicationId) + ';'    
     WHEN @TableName = 'Property'  
     THEN 'SELECT TOP 1 ' + @ColumnName + ' FROM Property WHERE ApplicationID = ' + CONVERT(VARCHAR(100), @applicationId) + ';'   
     WHEN @TableName = 'Document'  
     THEN 'SELECT ' + @ColumnName + ' FROM Document WHERE DocumentID = ' + CONVERT(VARCHAR(100), @documentId) + ';'   
     ELSE    
   ''    
     END;    
    
   EXEC sp_executesql @SQL, N'@OutValue NVARCHAR(100) OUTPUT', @OutValue = @ReturnValue OUTPUT;      
  END    
  ELSE  
  BEGIN  
  SET @ReturnValue = @expression;  
  END  
    
  RETURN;    
END;

	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END

CREATE PROCEDURE dbo.sp_creatediagram
(
	@diagramname 	sysname,
	@owner_id		int	= null, 	
	@version 		int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId int
	declare @retval int
	declare @IsDbo	int
	declare @userName sysname
	if(@version is null or @diagramname is null)
	begin
		RAISERROR (N'E_INVALIDARG', 16, 1);
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID(); 
	select @IsDbo = IS_MEMBER(N'db_owner');
	revert; 
	
	if @owner_id is null
	begin
		select @owner_id = @theId;
	end
	else
	begin
		if @theId <> @owner_id
		begin
			if @IsDbo = 0
			begin
				RAISERROR (N'E_INVALIDARG', 16, 1);
				return -1
			end
			select @theId = @owner_id
		end
	end
	-- next 2 line only for test, will be removed after define name unique
	if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end

	insert into dbo.sysdiagrams(name, principal_id , version, definition)
			VALUES(@diagramname, @theId, @version, @definition) ;
	
	select @retval = @@IDENTITY 
	return @retval
END

CREATE PROCEDURE dbo.sp_dropdiagram
(
	@diagramname 	sysname,
	@owner_id	int	= null
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int

	if(@diagramname is null)
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT; 
	
	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	delete from dbo.sysdiagrams where diagram_id = @DiagId;

	return 0;
END

