CREATE PROCEDURE [dbo].[spECMGetMetaDataForHPTRIM_KSC](
	@ApplicationID int,
	@DocumentID int,
	@CurrentStaffID int = 0,
	@ReferralAgencyID int = 0,
	@InspectionID int = 0,
	@AddresseeType varchar(100)='',
	@AddresseeID int = 0,
	@ApplicantAccountID INT = 0,
	@IsRelationOnly bit = 0,
	@AddresseeTypeID INT = 0,
	@AuthorTypeID INT = 0
)
AS
BEGIN

	DECLARE @DANumber varchar(250)
	DECLARE @UploadedBy INT
	DECLARE @UploaderName VARCHAR(300)
	
	SET @DANumber = (SELECT Top 1 StandardParcelIdentifier FROM Property WHERE ApplicationID = @ApplicationID)
	
	IF (@DANumber IS NULL OR @DANumber = '')
	BEGIN
	SET @DANumber ='N/A'
	END

	DECLARE @ApplicationTypeID INT;
	DECLARE @LicenceID	 INT;
	SELECT @ApplicationTypeID = A.ApplicationTypeID, @LicenceID = A.LicenceID FROM Application A WHERE A.ApplicationID = @ApplicationID
	
	DECLARE
	--CONTAINER RECORD METADATA
	@ContainerClassification VARCHAR(MAX), 
	@ContainerTitle VARCHAR(MAX), 
	@ContainerDateCreated DATETIME, 	
	@LANumber VARCHAR(MAX),
	@ContainerAssigneeEmailAddress VARCHAR(200),
	@ContainerAssigneeFirstName  VARCHAR(200),
	@ContainerAssigneeLastName  VARCHAR(200),
	@IsInternalAssignee VARCHAR(100),
	@SignOffStaffAccountID INT,
	
	--APPLICATION RECORD METADATA
	@DocumentTitle VARCHAR(MAX),
	@DocumentDateCreated DATETIME,
	@DocumentCertificateOfTitile VARCHAR(MAX),
	@AuthorEmailAddress VARCHAR(300), 
	@AuthorFirstName VARCHAR(300), 
	@AuthorLastName VARCHAR(300), 
	@IsInternalAuthor VARCHAR(100),	
	@AuthorAddressLines VARCHAR(100),
	@AuthorCity  VARCHAR(100),
	@AuthorState VARCHAR(100) ,
	@AuthorPostcode VARCHAR(100),
	@AuthorRegion VARCHAR(100),
	@AuthorCountry VARCHAR(100),

	@AddresseeEmailAddress VARCHAR(300), 
	@AddresseeFirstName VARCHAR(300), 
	@AddresseeLastName VARCHAR(300), 	
	@AddresseeAddressLines VARCHAR(100),
	@AddresseeCity  VARCHAR(100),
	@AddresseeState VARCHAR(100) ,
	@AddresseePostcode VARCHAR(100),
	@AddresseeRegion VARCHAR(100),
	@AddresseeCountry VARCHAR(100),
	@IsInternalAddressee VARCHAR(100),

	@DocumentNotes VARCHAR(150);

	SELECT TOP 1 @SignOffStaffAccountID = A.SignoffStaffID FROM Application A WHERE A.ApplicationID =  @ApplicationID

	--##### DEFINE CLASSIFICATION SCHEME FOR EACH EACH APPLICATION TYPE #####--
	SELECT TOP 1 @ContainerClassification = Classification
	FROM HPTrimClassifications WHERE
	LicenceID = @LicenceID
	AND ApplicationTypeID = @ApplicationTypeID

	
	--WITH NEW ENHANCEMENT THE USER WILL NOW MANUALLY SELECT WHO IS THE AUTHOR & ADDRESSEE OF THE DOCUMENT
	SELECT  @UploadedBy = D.UploadedBy, @DocumentNotes = LEFT(TRIM(D.Comments),125), @UploaderName = D.UploaderName FROM Document D WHERE D.DocumentID =  @DocumentID
	--1: Applicant; 2: Council
	IF(@AuthorTypeID = 1)
	BEGIN
		SELECT TOP 1 
		@AuthorEmailAddress = AC.Email,
		@AuthorFirstName = AC.FirstName,
		@AuthorLastName  = AC.LastName,
		@IsInternalAuthor = 'false',
		@AuthorAddressLines = 
		CASE
			WHEN NULLIF(AC.AD_UnitNo,'') IS NULL THEN ''
			ELSE AC.AD_UnitNo + ' / '
		END +		TRIM(ISNULL(NULLIF(AC.AD_StreetNumber,''),'') + ' ' + ISNULL(NULLIF(AC.AD_StreetName,''),'')),
		@AuthorCity = AC.AD_StreetName,
		@AuthorPostcode = AC.AD_PostCode,
		@AuthorRegion =  AC.AD_Suburb,
		@AuthorState = AC.AD_State,
		@AuthorCountry = AC.AD_Country
		FROM 
		ApplicationContact AC
		JOIN ContactGroup CG ON AC.ContactGroupID = CG.ContactGroupID
		WHERE AC.ApplicationID = @ApplicationID
		AND CG.ContactGroupName = 'Applicant'
	END
	--IF IT IS NOT APPLICANT IT COULD BE COUNCIL OR SOME OTHER USER THROUGH WORKFLOW
	ELSE
	BEGIN 
		--THIS IS REQUIRED FEE RECEIPTS
		IF(@UploadedBy IS NOT NULL AND @UploadedBy = 3 AND @UploaderName LIKE '%System%')
		BEGIN
			SELECT 
			@AuthorEmailAddress = 'greenlight-noreply@e-vis.com.au', 
			@AuthorFirstName = 'Greenlight',
			@AuthorLastName = 'E-VIS',
			@IsInternalAuthor = 'true'
		END
		ELSE
		-- THIS IS FOR INTERNAL STAFF UPLOADED 
		BEGIN
			SELECT 
			@AuthorEmailAddress = SA.Email,
			@AuthorFirstName = SA.FirstName,
			@AuthorLastName = SA.LastName,
			@IsInternalAuthor = 'true'
			FROM StaffAccount SA WHERE SA.StaffAccountID = @SignOffStaffAccountID
		END
	END		
	--#### AUTHOR  END ####--
	
	--##### ADDRESSEE DETAILS #####--
	-- 0: Applicant; 1: Staff; 2: Referral; 3: System; 4: Inspector
	SELECT  @UploadedBy = D.UploadedBy FROM Document D WHERE D.DocumentID =  @DocumentID
	IF(@AddresseeTypeID = 1)
	BEGIN
		SELECT TOP 1
		@AddresseeEmailAddress = AC.Email,
		@AddresseeFirstName = AC.FirstName,
		@AddresseeLastName = AC.LastName,
		@IsInternalAddressee = 'false',
		@AddresseeAddressLines = 
		CASE
			WHEN NULLIF(AC.AD_UnitNo,'') IS NULL THEN ''
			ELSE AC.AD_UnitNo + ' / '
		END + TRIM(ISNULL(NULLIF(AC.AD_StreetNumber,''),'') + ' ' + ISNULL(NULLIF(AC.AD_StreetName,''),'')),
		@AddresseeCity = AC.AD_Suburb,
		@AddresseePostcode = AC.AD_PostCode,
		@AddresseeRegion =  AC.AD_Suburb,
		@AddresseeState = AC.AD_State,
		@AddresseeCountry = AC.AD_Country
		FROM ApplicationContact AC
		JOIN ContactGroup CG ON AC.ContactGroupID = CG.ContactGroupID
		WHERE AC.ApplicationID = @ApplicationID
		AND CG.ContactGroupName = 'Applicant'
	END	
	ELSE
	BEGIN
		IF(@UploadedBy IS NOT NULL AND @UploadedBy = 3)
		BEGIN
			IF(NULLIF(@AddresseeType,'') IS NOT NULL AND @AddresseeID > 0)
			BEGIN
				IF(@AddresseeType = 'OnlinePayment')
				BEGIN
					SELECT 
					@AddresseeEmailAddress = FI.Payee_Email,
					@AddresseeFirstName = FI.Payee_FirstName,
					@AddresseeLastName = FI.Payee_LastName,
					@IsInternalAddressee = 'false',
					@AddresseeAddressLines = FI.Payee_Address				
					FROM OnlinePaymentFeeInfo FI WHERE FI.OnlinePaymentFeeInfoID = @AddresseeID
				END
				IF(@AddresseeType = 'Applicant')
				BEGIN
					SELECT TOP 1
					@AddresseeEmailAddress = AC.Email,
					@AddresseeFirstName = AC.FirstName,
					@AddresseeLastName = AC.LastName,
					@IsInternalAddressee = 'false',
					@AddresseeAddressLines = 
					CASE
						WHEN NULLIF(AC.AD_UnitNo,'') IS NULL THEN ''
						ELSE AC.AD_UnitNo + ' / '
					END + TRIM(ISNULL(NULLIF(AC.AD_StreetNumber,''),'') + ' ' + ISNULL(NULLIF(AC.AD_StreetName,''),'')),
					@AddresseeCity = AC.AD_Suburb,
					@AddresseePostcode = AC.AD_PostCode,
					@AddresseeRegion =  AC.AD_Suburb,
					@AddresseeState = AC.AD_State,
					@AddresseeCountry = AC.AD_Country
					FROM ApplicationContact AC					
					WHERE AC.ApplicationID = @ApplicationID 
					AND AC.ApplicationContactID =  @AddresseeID
				END
			END
		END
		ELSE
		BEGIN
		SELECT
			@AddresseeEmailAddress = 'applications.devcompliance@kempsey.nsw.gov.au',
			@AddresseeFirstName = 'Kempsey Shire Council',
			@AddresseeLastName  = null,
			@IsInternalAddressee = 'true'		
		END
	END
	--#### ADDRESSEE  END ####--

	
	SELECT 
	TOP 1 
	--CONTAINER METADATA
	@ContainerClassification = @ContainerClassification,
	@ContainerTitle = TRIM(' - ' FROM
CASE WHEN NULLIF(A.Description,'') IS NULL THEN '' ELSE A.Description END +
CASE WHEN NULLIF([dbo].[fnGetApplicantName](A.ApplicationID),'') IS NULL THEN '' ELSE ' - '+[dbo].[fnGetApplicantName](A.ApplicationID) END +
CASE WHEN NULLIF([dbo].[fnGetPropertyAddressForApplication](A.ApplicationID),'') IS NULL THEN '' ELSE ' - ' + [dbo].[fnGetPropertyAddressForApplication](A.ApplicationID) END + ' - '+ISNULL(A.ApplicationNo,A.ReferenceNo)),
	@ContainerDateCreated = GETDATE()-1,	
	@LANumber = [dbo].[fnGetPropertyLotDPForApplication](A.ApplicationID),
	@ContainerAssigneeEmailAddress = 'greenlight-noreply@e-vis.com.au',
	@ContainerAssigneeFirstName = 'Greenlight',
	@ContainerAssigneeLastName = 'E-VIS',
	@IsInternalAssignee ='true',

	-- APPLICATION RECORD METADATA
	@DocumentTitle = TRIM(' - ' FROM
CASE WHEN NULLIF(DT.DocumentTypeName,'') IS NULL THEN '' ELSE DT.DocumentTypeName END +
CASE WHEN NULLIF(D.FileName,'') IS NULL THEN '' ELSE ' - '+D.FileName END +
CASE WHEN NULLIF([dbo].[fnGetApplicantName](A.ApplicationID),'') IS NULL THEN '' ELSE ' - '+[dbo].[fnGetApplicantName](A.ApplicationID) END +
CASE WHEN NULLIF([dbo].[fnGetPropertyAddressForApplication](A.ApplicationID),'') IS NULL THEN '' ELSE ' - ' + [dbo].[fnGetPropertyAddressForApplication](A.ApplicationID) END + ' - '+ISNULL(A.ApplicationNo,A.ReferenceNo)),
	@DocumentDateCreated = D.DateInserted-1,
	@AuthorEmailAddress = ISNULL(@AuthorEmailAddress,'greenlight-noreply@e-vis.com.au') ,
	@AuthorFirstName = ISNULL(@AuthorFirstName,'Greenlight'),
	@AuthorLastName = ISNULL(@AuthorLastName,'E-VIS'),
	@IsInternalAuthor = ISNULL(@IsInternalAuthor,'false'),
	@AddresseeEmailAddress = ISNULL(@AddresseeEmailAddress,'greenlight-noreply@e-vis.com.au'),
	@AddresseeFirstName = ISNULL(@AddresseeFirstName,'Greenlight'),
	@AddresseeLastName = ISNULL(@AddresseeLastName,'E-VIS'),
	@IsInternalAddressee = ISNULL(@IsInternalAddressee,'false'),
	@DocumentCertificateOfTitile = [dbo].[fnGetPropertyLotDPForApplication](A.ApplicationID)
	FROM Document D
	JOIN Application A ON D.ApplicationID = A.ApplicationID AND A.ApplicationID =  @ApplicationID
	LEFT JOIN DocumentType DT ON D.DocumentTypeID = DT.DocumentTypeID
	WHERE D.DocumentID = @DocumentID

	-- ADD RECORD TO DATABASE FOR AUDIT PURPOSE	
	INSERT INTO [dbo].[HPTrimAudit]
			   ([ApplicationID]
			   ,[DateCreated]
			   ,[ContainerClassification]
			   ,[ContainerTitle]
			   ,[ContainerDateCreated]			   
			   ,[ContainerCertificateOfTitile]
			   ,[DocumentTitle]
			   ,[DocumentDateCreated]
			   ,[AuthorEmailAddress]
			   ,[AuthorFirstName]
			   ,[AuthorLastName]
			   ,[IsInternalAuthor]
			   ,[AddresseeEmailAddress]
			   ,[AddresseeFirstName]
			   ,[AddresseeLastName]
			   ,[IsInternalAddressee]
			   ,[DocumentCertificateOfTitile]
			   ,[ContainerAssigneeEmailAddress]
			   ,[ContainerAssigneeFirstName]
			   ,[ContainerAssigneeLastName]
			   ,[IsInternalAssignee]
			   ,[DocumentID]
			   ,[CurrentStaffID]
			   ,[ReferralAgencyID]
			   ,[InspectionID]
			   ,[AddresseeType]
			   ,[AddresseeID]
			   ,[ApplicantID]
			   ,[IsRelationOnly]
			   ,[AddresseeTypeID]
			   ,[AuthorTypeID]
			   )
		 VALUES		
			   (@ApplicationID
			   ,GETDATE()
			   ,@ContainerClassification
			   ,@ContainerTitle
			   ,@ContainerDateCreated			   
			   ,@LANumber
			   ,@DocumentTitle
			   ,@DocumentDateCreated
			   ,@AuthorEmailAddress
			   ,@AuthorFirstName
			   ,@AuthorLastName
			   ,@IsInternalAuthor
			   ,@AddresseeEmailAddress
			   ,@AddresseeFirstName
			   ,@AddresseeLastName
			   ,@IsInternalAddressee
			   ,@DocumentCertificateOfTitile
			   ,@ContainerAssigneeEmailAddress
			   ,@ContainerAssigneeFirstName
			   ,@ContainerAssigneeLastName
			   ,@IsInternalAssignee
			   ,@DocumentID
			   ,@CurrentStaffID
			   ,@ReferralAgencyID
			   ,@InspectionID
			   ,@AddresseeType
			   ,@AddresseeID
			   ,@ApplicantAccountID
			   ,@IsRelationOnly
			   ,@AddresseeTypeID
			   ,@AuthorTypeID
			   )

	SELECT  
	--CONTAINER METADATA
	@ContainerClassification AS 'ContainerClassification',
	@ContainerTitle AS 'ContainerTitle',
	@ContainerDateCreated AS 'ContainerDateCreated',	
	@LANumber AS 'LANumber',
	@LANumber AS 'DocumentCertificateOfTitile',
	@ContainerAssigneeEmailAddress AS 'AssigneeEmailAddress',
	@ContainerAssigneeFirstName AS 'AssigneeFirstName',
	@ContainerAssigneeLastName AS 'AssigneeLastName',
	@IsInternalAssignee AS 'IsInternalAssignee',
	'Greenlight Application Folder' AS 'ContainerRecordTypeName',
	--@DocumentID AS 'LongNumber',
	--APPLICATION RECORD METADATA
	@DocumentTitle AS 'DocumentTitle',
	@DocumentDateCreated  AS 'DocumentDateCreated',
	@AuthorEmailAddress AS 'AuthorEmailAddress',
	@AuthorFirstName AS 'AuthorFirstName',
	@AuthorLastName AS 'AuthorLastName',
	@IsInternalAuthor AS 'IsInternalAuthor',
	@AddresseeEmailAddress AS 'AddresseeEmailAddress',
	@AddresseeFirstName AS 'AddresseeFirstName',
	@AddresseeLastName AS 'AddresseeLastName',
	@IsInternalAddressee AS 'IsInternalAddressee',
	@DocumentCertificateOfTitile  AS 'DocumentCertificateOfTitile',
	@IsRelationOnly AS 'IsRelationOnly',
	@AuthorAddressLines AS 'AuthorAddressLines',
	@AuthorCity AS 'AuthorCity',
	@AuthorState AS 'AuthorState' ,
	@AuthorPostcode AS 'AuthorPostcode',
	@AuthorCountry AS 'AuthorCountry',
	@AuthorRegion AS 'AuthorRegion',
	@AddresseeAddressLines AS 'AddresseeAddressLines',
	@AddresseeCity AS 'AddresseeCity',
	@AddresseeState AS 'AddresseeState' ,
	@AddresseePostcode AS 'AddresseePostcode',
	@AddresseeCountry AS 'AddresseeCountry',
	@AddresseeRegion AS 'AddresseeRegion',
	@DocumentNotes AS 'DocumentNotes'

END
